arguments.command:
cd /tmp/sv-13dfdc33746842ca85ec35ae2dc58cce/simple-solution && dotnet list package --format json 2>/dev/null | python3 -c "import sys,json; data=json.load(sys.stdin); json.dump(data,open('after-cpm-packages.json','w'),indent=2)" && python3 -c "
import json
b=json.load(open('baseline-packages.json'))
a=json.load(open('after-cpm-packages.json'))
def pkgs(d):
    r={}
    for p in d['projects']:
        for f in p['frameworks']:
            for pkg in f.get('topLevelPackages',[]):
                r.setdefault(pkg['id'],[]).append(pkg['resolvedVersion'])
    return r
bp,ap=pkgs(b),pkgs(a)
if bp==ap: print('MATCH: All package versions identical')
else: print('DIFF:',{k:(bp.get(k),ap.get(k)) for k in set(list(bp)+list(ap)) if bp.get(k)!=ap.get(k)})
"

